"""Compare matched native static/moving runs and measured scalar elbow response."""
from pathlib import Path
import json,hashlib
import numpy as np
from scipy.spatial.transform import Rotation
P=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,x):
 with p.open('x')as f:json.dump(x,f,indent=2,ensure_ascii=False,allow_nan=False)
def main():
 folders=[P/'native_v2/static_cradle',P/'native_v3/elbow_motion'];centre=np.array(read(P/'analysis_v3/static_cradle/verification.json')['source_body_bbox_centre_G_m']);paths=[Path(__file__).resolve(),P/'analysis_v3/static_cradle/verification.json',P/'analysis_v4/elbow_motion/verification.json',P/'motion_candidate_v1/gate_release.json'];paths+=[f/x for f in folders for x in ('initial_values.json','trace.json','media/effort_control_rows.json','media/elbow_motion_configuration.json','media/physics_endpoint_contacts.json')];inputs={str(p):sha(p)for p in paths};initial=[read(f/'initial_values.json')for f in folders];assert initial[0]['native_initial_state']==initial[1]['native_initial_state'];traces=[read(f/'trace.json')for f in folders];bc=[];rots=[]
 for trace in traces:
  rot=[Rotation.from_quat(t['quaternion_xyzw'])for t in trace];rots.append(rot);bc.append(np.array([np.array(t['position_W_m'])+r.apply(centre)for t,r in zip(trace,rot)]))
 before_delta=np.linalg.norm(bc[1][:151]-bc[0][:151],axis=1);assert max(before_delta)<1e-12;assert all(traces[0][k]==traces[1][k]for k in range(151));pos=np.linalg.norm(bc[1][150:]-bc[0][150:],axis=1)*1000;angles=np.array([float(np.rad2deg((a.inv()*b).magnitude()))for a,b in zip(rots[0][150:],rots[1][150:])]);controls=[read(f/'media/effort_control_rows.json')['rows']for f in folders];motion=read(folders[1]/'media/elbow_motion_configuration.json');right=read(folders[1]/'media/effort_configuration.json')['right_indices'];i=right.index(motion['index']);response=np.array([b['q_right_rad'][i]-a['q_right_rad'][i]for a,b in zip(*controls)]);command=np.array([r['posture_target_rad'][motion['index']]-initial[1]['q_ref_rad'][motion['index']]for r in controls[1]]);window=slice(600,1080);corr=float(np.corrcoef(command[window],response[window])[0,1]);tracking=float(np.rad2deg(np.sqrt(np.mean((response[window]-command[window])**2))));s=read(P/'analysis_v4/elbow_motion/verification.json')['cases']['elbow_motion'];elapsed=np.arange(150,301)/60
 actual_moving=bool(np.rad2deg(np.ptp(response[window]))>2 and corr>.9);small_effect=bool(actual_moving and pos.max()<2 and angles.max()<1 and s['right_distal_after_2p5_presence']==0 and s['endpoints']['head_presence']==0 and s['endpoints']['left_arm_hand_presence']==0)
 save(P/'elbow_comparison_trace_v1.json',{'input_sha256':inputs,'time_s':elapsed.tolist(),'same_time_body_centre_delta_mm':pos.tolist(),'same_time_rotation_delta_deg':angles.tolist(),'physics_time_s':(np.arange(1200)/240).tolist(),'elbow_command_delta_deg':np.rad2deg(command).tolist(),'elbow_actual_moving_minus_static_deg':np.rad2deg(response).tolist()})
 save(P/'elbow_comparison_v1.json',{'input_sha256':inputs,'same_native_initial_state_exact':True,'same_native_trace_to_2p5s_exact':True,'command_only_elbow_scalar':'R_Elbow_y','command_amplitude_deg':float(np.rad2deg(motion['amplitude_rad'])),'native_elbow_response_peak_to_peak_deg':float(np.rad2deg(np.ptp(response[window]))),'native_elbow_response_command_correlation':corr,'native_elbow_tracking_RMSE_deg':tracking,'max_same_time_body_centre_difference_mm':float(pos.max()),'max_same_time_rotation_difference_deg':float(angles.max()),'final_same_time_body_centre_difference_mm':float(pos[-1]),'final_same_time_rotation_difference_deg':float(angles[-1]),'actual_elbow_movement_verified':actual_moving,'small_elbow_influence_diagnostic_passed':small_effect,'temporary_comparison_thresholds':{'body_mm':2,'rotation_deg':1,'elbow_response_peak_to_peak_min_deg':2,'response_correlation_min':.9,'right_distal_after_2p5_contacts':0},'scope':'one matched5s pair, elbow target2deg one cycle; not larger motion, fret/strike, anatomical armpit realism or repeatability certification'});assert all(sha(Path(p))==h for p,h in inputs.items());print(json.dumps(read(P/'elbow_comparison_v1.json'),indent=2))
if __name__=='__main__':main()
